import pandas as pd
import numpy as np

def get_turn_scores(rolls):
    if not rolls or any(np.isnan(rolls)):
        return {cat: 0 for cat in ['High and Often', 'Summation', 'Highs and Lows', 'Only two numbers', 'All the numbers', 'Ordered subset of four']}

    scores = {}
    rolls = [int(r) for r in rolls]

    # 1. High and Often
    max_roll = max(rolls)
    scores['High and Often'] = max_roll * rolls.count(max_roll)

    # 2. Summation
    scores['Summation'] = sum(rolls)

    # 3. Highs and Lows
    scores['Highs and Lows'] = max(rolls) * min(rolls) * (max(rolls) - min(rolls))

    # 4. Only two numbers
    if len(set(rolls)) <= 2:
        scores['Only two numbers'] = 30
    else:
        scores['Only two numbers'] = 0

    # 5. All the numbers
    if set(rolls) == {1, 2, 3, 4, 5, 6}:
        scores['All the numbers'] = 40
    else:
        scores['All the numbers'] = 0

    # 6. Ordered subset of four
    scores['Ordered subset of four'] = 0
    for i in range(len(rolls) - 3):
        window = rolls[i:i+4]
        # Increasing
        if window[1] == window[0] + 1 and window[2] == window[1] + 1 and window[3] == window[2] + 1:
            scores['Ordered subset of four'] = 50
            break
        # Decreasing
        if window[1] == window[0] - 1 and window[2] == window[1] - 1 and window[3] == window[2] - 1:
            scores['Ordered subset of four'] = 50
            break

    return scores

def calculate_game_score(turns_rolls):
    # turns_rolls is a list of lists of rolls
    if len(turns_rolls) == 0:
        return 0
    if len(turns_rolls) == 1:
        s = get_turn_scores(turns_rolls[0])
        return max(s.values())

    # Standard 2 turns
    s1 = get_turn_scores(turns_rolls[0])
    s2 = get_turn_scores(turns_rolls[1])

    categories = list(s1.keys())
    max_score = 0
    for i in range(len(categories)):
        for j in range(len(categories)):
            if i == j:
                continue
            score = s1[categories[i]] + s2[categories[j]]
            if score > max_score:
                max_score = score
    return max_score

# Load data
df = pd.read_excel('/root/data.xlsx', sheet_name='Data', skiprows=7)
# Use the correct columns
# Unnamed: 3 is Game number
# Unnamed: 4-9 are Rolls
df['game'] = pd.to_numeric(df['Unnamed: 3'], errors='coerce')
rolls_cols = ['Unnamed: 4', 'Unnamed: 5', 'Unnamed: 6', 'Unnamed: 7', 'Unnamed: 8', 'Unnamed: 9']

# Group by game
game_to_rolls = {}
for g, group in df.dropna(subset=['game']).groupby('game'):
    game_id = int(g)
    turns = []
    for _, row in group.iterrows():
        rolls = row[rolls_cols].tolist()
        if not any(pd.isna(rolls)):
            turns.append([int(r) for r in rolls])
    game_to_rolls[game_id] = turns

game_scores = {}
for g in range(1, 3001):
    turns = game_to_rolls.get(g, [])
    game_scores[g] = calculate_game_score(turns)

p1_wins = 0
p2_wins = 0

for m in range(1, 1501):
    g1 = 2*m - 1
    g2 = 2*m
    s1 = game_scores[g1]
    s2 = game_scores[g2]

    if s1 > s2:
        p1_wins += 1
    elif s2 > s1:
        p2_wins += 1

print(p1_wins - p2_wins)
